/**
 * Created by Estevao on 15-01-2015.
 *
 * HTML → Markdown conversion behavior lives in test/functional/makemarkdown/cases/. What
 * remains here asserts an object identity the fixture format cannot express.
 */

describe('showdown.Converter', function () {
  'use strict';


  describe('makeMarkdown() parses into an inert document', function () {
    let converter = new showdown.Converter();

    it('should parse untrusted html in an inert document (no script/onerror execution)', function () {
      // parseHTML must not reuse the live ambient document; it parses into an inert
      // document (createHTMLDocument) so <img onerror>/<svg onload> never fire client-side.
      let div = showdown.helper.parseHTML('<img src=x onerror="window.__xss=1">');
      expect(div.ownerDocument).not.toBe(showdown.helper.document);
      // sanity: the markup still parsed and is walkable
      expect(converter.makeMarkdown('<img src=x onerror="window.__xss=1">')).toBe('![](<x>)');
    });

  });
});

test/unit/showdown.Converter.makeHtml.js.source:
/**
 * Created by Tivie on 15-01-2015.
 *
 * makeHtml() coverage that a fixture cannot express. Per-option conversion behavior lives in
 * test/functional/makehtml/cases/features.testsuite.json (and the spec suites); what remains
 * here asserts invocation counts, thrown errors, post-conversion accessor state, and the one
 * option whose effect the functional harness normalizes away (see omitExtraWLInCodeBlocks).
 */


describe('showdown.Converter', function () {
  'use strict';

  describe('Converter.options extensions', function () {
    let runCount;
    showdown.extension('testext', function () {
      return [{
        type: 'output',
        filter: function (text) {
          runCount = runCount + 1;
          return text;
        }
      }];
    });

    let converter = new showdown.Converter({extensions: ['testext']});

    it('output extensions should run once', function () {
      runCount = 0;
      converter.makeHtml('# testext');
      expect(runCount).toBe(1);
    });
  });

  describe('makeHtml() with option omitExtraWLInCodeBlocks', function () {
    // Deliberately NOT a fixture: the option's only effect is the trailing newline before
    // `</code>`, and the functional harness prettifies both sides with diffable-html, which
    // re-indents `<pre><code>` content and normalizes that newline away. A fixture would
    // therefore pass identically with the option on or off.
    let converter = new showdown.Converter({omitExtraWLInCodeBlocks: true}),
        text = 'var foo = bar;',
        html = converter.makeHtml('    ' + text);
    it('should omit extra line after code tag', function () {
      let expectedHtml = '<pre><code>' + text + '</code></pre>';
      expect(html).toBe(expectedHtml);
    });
  });

  describe('makeHtml() with option headerIds', function () {
    it('should throw a TypeError for an invalid headerIds value', function () {
      expect(function () {
        new showdown.Converter({ headerIds: 3 });
      }).toThrow();
    });
  });

  describe('makeHtml() with option metadata', function () {
    let converter = new showdown.Converter(),
        text1 =
          '---SIMPLE\n' +
          'foo: bar\n' +
          'baz: bazinga\n' +
          '---\n',
        text2 =
          '---TIVIE\n' +
          'a: b\n' +
          'c: 123\n' +
          '---\n';

    it('should correctly set metadata', function () {
      converter.setOption('metadata', true);

      let expectedHtml = '',
          expectedObj = {foo: 'bar', baz: 'bazinga'},
          expectedRaw = 'foo: bar\nbaz: bazinga',
          expectedFormat = 'SIMPLE';
      expect(converter.makeHtml(text1)).toBe(expectedHtml);
      expect(converter.getMetadata()).toEqual(expectedObj);
      expect(converter.getMetadata(true)).toBe(expectedRaw);
      expect(converter.getMetadataFormat()).toBe(expectedFormat);
    });

    it('consecutive calls should reset metadata', function () {
      converter.makeHtml(text2);
      let expectedObj = {a: 'b', c: '123'},
          expectedRaw = 'a: b\nc: 123',
          expectedFormat = 'TIVIE';
      expect(converter.getMetadata()).toEqual(expectedObj);
      expect(converter.getMetadata(true)).toBe(expectedRaw);
      expect(converter.getMetadataFormat()).toBe(expectedFormat);
    });
  });
});

test/unit/showdown.htmlBlock.js.source:
import { describe, it, expect } from 'vitest';
import showdown from 'virtual:showdown';

describe('makehtml.htmlBlock subparser', () => {
  it('passes a balanced raw HTML block through verbatim (legacy scanner)', () => {
    const converter = new showdown.Converter();
    expect(converter.makeHtml('some text\n\n<div class="foo">\nraw & content\n</div>\n\nmore text')).toBe(
      '<p>some text</p>\n<div class="foo">\nraw & content\n</div>\n<p>more text</p>'
    );
  });

  it('parses the interior of a markdown="1" block as markdown', () => {
    const converter = new showdown.Converter();
    expect(converter.makeHtml('<div markdown="1">\n*em* text\n</div>')).toBe(
      '<div markdown="1"><p><em>em</em> text</p></div>'
    );
  });

  it('treats --!> as an HTML comment terminator so commented content cannot leak (legacy and cmSpec)', () => {
    const legacy = new showdown.Converter();
    expect(legacy.makeHtml('<!-- this "comment" ends with a bang --!>')).toBe(
      '<!-- this "comment" ends with a bang --!>'
    );
    const cm = new showdown.Converter({ cmSpec: true });
    expect(cm.makeHtml('<!-- this "comment" ends with a bang --!>')).toBe(
      '<!-- this "comment" ends with a bang --!>'
    );
  });

  it('recognizes CommonMark type 7 HTML blocks: a complete tag alone on its line (cmSpec)', () => {
    const converter = new showdown.Converter({ cmSpec: true });
    expect(converter.makeHtml('a paragraph\n\n<span>')).toBe(
      '<p>a paragraph</p>\n<span>'
    );
    expect(converter.makeHtml('a paragraph\n\n</div>')).toBe(
      '<p>a paragraph</p>\n</div>'
    );
  });
});

test/unit/showdown.safeMode.js.source:
/**
 * safeMode option — white-box coverage.
 *
 * The option's behavior (URL scheme allowlist, raw-HTML escaping, event-handler stripping and
 * their interactions) lives in the `safeMode` section of
 * test/functional/makehtml/cases/features.testsuite.json. Only the case below stays here: it
 * drives the subparser directly because no converter input reaches that intermediate state.
 */
describe('showdown.Converter safeMode option', function () {
  'use strict';

  describe('disallowedHtmlTags subparser', function () {
    it('should leave already-escaped malformed-tag text untouched (no in-place corruption)', function () {
      // A malformed tag (e.g. `<a/href=…>`, `<img/onerror=…>`) is entity-escaped to inert
      // `&lt;…&gt;` text upstream. The disallowedHtmlTags safeMode sanitizers operate per real
      // `<…>` tag only, so this escaped text passes through verbatim — matching it would strip
      // characters out of the middle of the inert text and corrupt it.
      let opts = showdown.getDefaultOptions();
      opts.safeMode = true;
      let globals = {gHtmlBlocks: [], gHtmlRawBlocks: [], gHtmlSpans: [], ghCodeBlocks: [], converter: new showdown.Converter()},
          escaped = '&lt;a/href=&quot;javascript:alert(1)&quot;&gt; and &lt;img/onerror=alert(1)&gt;';
      expect(showdown.subParser('makehtml.disallowedHtmlTags')(escaped, opts, globals)).toBe(escaped);
    });
  });
});

